package com.wizzadrds.theworldremembers;
import com.wizzadrds.theworldremembers.village.*; import net.fabricmc.fabric.api.gametest.v1.GameTest; import net.minecraft.gametest.framework.GameTestHelper; import net.minecraft.world.entity.EntityTypes;
public final class VillageEventGameTest { @GameTest public void deathCreatesVillageEvent(GameTestHelper c){var v=c.spawn(EntityTypes.VILLAGER,2,1,2);c.runAtTickTime(1,()->{TheWorldRemembers.processWorld(c.getLevel());var vm=VillageManager.get(c.getLevel().getServer());var id=vm.all().iterator().next().villageId();v.kill();c.runAtTickTime(2,()->{var events=VillageEventManager.get(c.getLevel().getServer()).get(id);if(events.stream().noneMatch(e->e.type().equals("npc_died"))){c.fail("Village death event was not recorded");return;}c.succeed();});});}}
